export function normalizeLocale(value) {
    if (!value)
        return null;
    const normalized = value.trim().replaceAll('_', '-').toLowerCase();
    if (!normalized)
        return null;
    const [primary, ...restParts] = normalized.split('-');
    const rest = restParts.join('-');
    if (primary === 'zh') {
        return rest.includes('hant') || rest.includes('tw') || rest.includes('hk') || rest.includes('mo')
            ? 'zh-Hant'
            : 'zh-CN';
    }
    if (primary && supportedLocales.includes(primary)) {
        return primary;
    }
    return null;
}
export function resolveAuthLocale(windowRef, locale) {
    if (locale !== 'auto')
        return normalizeLocale(locale) ?? 'en';
    const documentLocale = normalizeLocale(windowRef.document.documentElement.lang);
    if (documentLocale)
        return documentLocale;
    const browserLocales = windowRef.navigator.languages?.length
        ? windowRef.navigator.languages
        : [windowRef.navigator.language];
    for (const browserLocale of browserLocales) {
        const normalized = normalizeLocale(browserLocale);
        if (normalized)
            return normalized;
    }
    return 'en';
}
export function resolveAuthMessages(locale, overrides) {
    return { ...authMessages.en, ...authMessages[locale], ...overrides };
}
export function getLocaleDirection(locale) {
    return locale === 'ar' ? 'rtl' : 'ltr';
}
